import test from 'node:test';import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import {join} from 'node:path';import {execFileSync} from 'node:child_process';import {createHash} from 'node:crypto';
import {inspectFocusedSnapshotArchive} from './focused-snapshot-reader.mjs';import {inspectFocusedFiles} from './focused-file-evidence.mjs';import {hash} from './manifest.mjs';
async function exercise(mutate){const directory=mkdtempSync(join(tmpdir(),'bonus-reader-model-'));try{
 const git=(...a)=>execFileSync('git',a,{cwd:directory,encoding:'utf8'}).trim();git('init','-q');mkdirSync(join(directory,'scripts'));const classifier='export const classification="model";';writeFileSync(join(directory,'scripts/gate-db-classify.ts'),classifier);git('add','.');git('-c','user.name=Fixture','-c','user.email=fixture@example.invalid','commit','-qm','model');const sha=git('rev-parse','HEAD'),runtime={node:'22.23.3',platform:'linux',arch:'x64'},files=['test/a.test.ts'],groups={NODB:files,DB:[]},start=new Date(Date.now()-120000).toISOString(),end=new Date(Date.now()-60000).toISOString();
 const expected={candidate:sha,controller:sha,baseline:sha,runId:11},raw={success:true,numPassedTests:1,numFailedTests:0,numTotalTests:1,numFailedTestSuites:0,testResults:[{name:'/home/runner/work/ai-hr/ai-hr/source/test/a.test.ts',status:'passed',assertionResults:[{status:'passed'}]}]};
 const report={schemaVersion:1,kind:'FOCUSED_ONLY',releaseEligible:false,sha,controller:sha,runId:'11',attempt:'1',runtime,files,groups,manifestHash:hash(JSON.stringify(files)),classifierHash:createHash('sha256').update(classifier).digest('hex'),healthBefore:{ok:true},healthAfter:{ok:true},batches:[{kind:'NODB',files,exitCode:0,processExitCode:0,signal:null,assertions:1}],exitCode:0,startedAt:start,endedAt:end};
 const run={id:11,repository:{id:1333414856,full_name:'StradaverseHub/ai-hr'},head_repository:{id:1333414856},head_sha:sha,head_branch:'main',workflow_id:395862645,path:'.github/workflows/alpha-focused-checks.yml',event:'workflow_dispatch',status:'completed',conclusion:'success',run_attempt:1,created_at:start,updated_at:end};
 const jobs=['resolve','selected-tests','typecheck','linux-build'].map((name,i)=>({id:i+1,name,run_id:11,head_sha:sha,head_branch:'main',run_attempt:1,status:'completed',conclusion:i<2?'success':'skipped',started_at:start,completed_at:end}));
 const input=join(directory,'input');mkdirSync(input);const model={report,raw,expected,reconstructed:{plan:{sha,controller:sha,migrationBase:sha,runtime,suite:files,units:[{kind:'nodb',files,pdfTools:false}],execution:{postgres:{memoryBytes:2147483648,jit:'on'}}},binding:{candidate:sha}}};if(mutate)mutate(model);
 writeFileSync(join(input,'focused.json'),JSON.stringify(model.report));writeFileSync(join(input,'nodb.vitest.json'),JSON.stringify(model.raw));const archivePath=join(directory,'focused-development-evidence.zip');execFileSync('python3',['-c','import sys,zipfile,pathlib; p=pathlib.Path(sys.argv[1]); z=zipfile.ZipFile(sys.argv[2],"w"); [z.write(f,f.name) for f in sorted(p.iterdir())]; z.close()',input,archivePath]);const bytes=readFileSync(archivePath),artifact={id:20,name:'focused-development-evidence',expired:false,size_in_bytes:bytes.length,digest:'sha256:'+createHash('sha256').update(bytes).digest('hex'),created_at:end,expires_at:new Date(Date.now()+86400000).toISOString(),workflow_run:{id:11,repository_id:1333414856,head_repository_id:1333414856,head_sha:sha,head_branch:'main'}};
 return await inspectFocusedSnapshotArchive({repository:directory,expected:model.expected,snapshot:{run,jobs,artifacts:[artifact]},reconstructed:model.reconstructed,archivePath,directory:join(directory,'observed')});
 }finally{rmSync(directory,{recursive:true,force:true});}}
test('cache reader preserves actual raw assertions, source identity and zero release authority',async()=>{const r=await exercise();assert.equal(r.passingFiles,1);assert.equal(r.failedFiles,0);assert.equal(r.originalFocusedExitCode,0);assert.equal(r.releaseAuthorized,false);});
for(const [name,mutate] of [['runtime drift',m=>m.report.runtime={...m.report.runtime,node:'22.23.4'}],['unobserved process exit',m=>m.report.batches[0].processExitCode=null],['hidden assertion',m=>m.raw.testResults[0].assertionResults[0].status='pending'],['foreign source',m=>m.report.sha='0'.repeat(40)],['foreign immutable plan',m=>m.reconstructed.plan.sha='0'.repeat(40)],['missing selected file',m=>m.raw.testResults=[]]])test('cached reader refuses '+name,async()=>assert.rejects(exercise(mutate)));
